#!/usr/bin/env python3
"""Release isolation gate for ANC v2.

Fail-Closed checks:
1. Public evidence dir only keeps README.
2. Legacy evidence path references are fully migrated (except explicit policy docs).
3. Registry/config fragments do not reference runtime_data/private-assets.
4. Registry contract verification passes.
5. Optional OpenClaw scope dry-run checks pass.
"""

from __future__ import annotations

import argparse
import json
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import List


@dataclass
class CheckResult:
    name: str
    passed: bool
    detail: str


def run(cmd: List[str], cwd: Path) -> subprocess.CompletedProcess[str]:
    return subprocess.run(cmd, cwd=str(cwd), text=True, capture_output=True, check=False)


def repo_root() -> Path:
    proc = subprocess.run(["git", "rev-parse", "--show-toplevel"], text=True, capture_output=True, check=False)
    if proc.returncode != 0:
        raise RuntimeError("not inside git repo")
    return Path(proc.stdout.strip()).resolve()


def check_public_evidence_placeholder(root: Path) -> CheckResult:
    evidence_dir = root / "docs/design/modules/evidence"
    if not evidence_dir.exists():
        return CheckResult("public_evidence_placeholder", False, "missing docs/design/modules/evidence")

    files = [p for p in evidence_dir.rglob("*") if p.is_file()]
    allowed = {evidence_dir / "README.md"}
    extra = [p for p in files if p not in allowed]
    if extra:
        sample = ", ".join(str(p.relative_to(root)) for p in extra[:5])
        return CheckResult(
            "public_evidence_placeholder",
            False,
            f"public evidence dir contains non-whitelist files (sample): {sample}",
        )
    return CheckResult("public_evidence_placeholder", True, "docs/design/modules/evidence only keeps README.md")


def check_legacy_path_refs(root: Path) -> CheckResult:
    cmd = [
        "rg",
        "-n",
        "docs/design/modules/evidence/",
        "--glob",
        "!docs/design/modules/evidence/**",
        "-g",
        "*.py",
        "-g",
        "*.md",
        "-g",
        "*.json",
        "-g",
        "*.sh",
    ]
    proc = run(cmd, root)
    if proc.returncode not in {0, 1}:
        return CheckResult("legacy_path_refs", False, f"rg failed: {proc.stderr.strip()}")

    allowed_prefixes = {
        "AGENTS.md:",
        "docs/architecture/release_isolation_policy.md:",
        "runtime_data/README.md:",
        "tools/release/release_isolation_gate.py:",
    }

    lines = [line for line in proc.stdout.splitlines() if line.strip()]
    unexpected = [line for line in lines if not any(line.startswith(prefix) for prefix in allowed_prefixes)]
    if unexpected:
        sample = "\n".join(unexpected[:20])
        return CheckResult("legacy_path_refs", False, f"unexpected legacy references:\n{sample}")
    return CheckResult("legacy_path_refs", True, "legacy evidence references migrated")


def check_no_private_assets_in_registry(root: Path) -> CheckResult:
    cmd = [
        "rg",
        "-n",
        "runtime_data/private-assets",
        "shared/registry",
        "config/openclaw.phase05.fragment.json",
        "config/openclaw.phase05.with-entry.fragment.json",
    ]
    proc = run(cmd, root)
    if proc.returncode == 1:
        return CheckResult("private_assets_registry_leak", True, "no private asset paths in registry/config fragments")
    if proc.returncode == 0:
        return CheckResult("private_assets_registry_leak", False, proc.stdout.strip())
    return CheckResult("private_assets_registry_leak", False, f"rg failed: {proc.stderr.strip()}")


def check_registry_verify(root: Path) -> CheckResult:
    cmd = ["python3", "shared/registry/registry_contract_tool.py", "verify"]
    proc = run(cmd, root)
    if proc.returncode != 0:
        detail = proc.stdout.strip() or proc.stderr.strip() or "registry verify failed"
        return CheckResult("registry_verify", False, detail)
    return CheckResult("registry_verify", True, (proc.stdout.strip() or "verify passed"))


def check_release_whitelist(root: Path) -> CheckResult:
    cmd = ["python3", "tools/release/generate_release_whitelist.py", "--strict"]
    proc = run(cmd, root)
    if proc.returncode != 0:
        detail = proc.stdout.strip() or proc.stderr.strip() or "release whitelist strict generation failed"
        return CheckResult("release_whitelist", False, detail)
    return CheckResult("release_whitelist", True, proc.stdout.strip() or "release whitelist generated")


def check_openclaw_scope_switch(root: Path) -> CheckResult:
    checks = []
    for scope in ("public", "dev"):
        cmd = [
            "python3",
            "tools/openclaw/switch_workspace.py",
            "--repo-root",
            str(root),
            "--scope",
            scope,
            "--dry-run",
        ]
        proc = run(cmd, root)
        checks.append((scope, proc.returncode, proc.stderr.strip(), proc.stdout.strip()))
        if proc.returncode != 0:
            return CheckResult(
                "openclaw_scope_switch",
                False,
                f"scope={scope} dry-run failed: {(proc.stderr.strip() or proc.stdout.strip())[:800]}",
            )
    return CheckResult("openclaw_scope_switch", True, "public/dev dry-run switch passed")


def check_openclaw_health(root: Path) -> CheckResult:
    cmd = ["openclaw", "health", "--json"]
    proc = run(cmd, root)
    if proc.returncode != 0:
        return CheckResult("openclaw_health", False, proc.stderr.strip() or "openclaw health failed")
    if '"ok": true' not in proc.stdout:
        return CheckResult("openclaw_health", False, "openclaw health returned non-ok payload")
    return CheckResult("openclaw_health", True, "openclaw health ok")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Run ANC v2 release isolation gate")
    parser.add_argument(
        "--verify-openclaw",
        action="store_true",
        help="Run OpenClaw runtime checks (health + scope dry-run switch).",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    root = repo_root()

    results = [
        check_public_evidence_placeholder(root),
        check_legacy_path_refs(root),
        check_no_private_assets_in_registry(root),
        check_release_whitelist(root),
        check_registry_verify(root),
    ]

    if args.verify_openclaw:
        results.append(check_openclaw_health(root))
        results.append(check_openclaw_scope_switch(root))

    passed = all(item.passed for item in results)
    report = {
        "passed": passed,
        "results": [
            {
                "name": item.name,
                "passed": item.passed,
                "detail": item.detail,
            }
            for item in results
        ],
    }
    print(json.dumps(report, ensure_ascii=False, indent=2))

    if not passed:
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Run M6 construction linkage audit and emit structured report."""

from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Set


ROUND_ID_RE = re.compile(r"^R-\d{8}-M6-[a-z0-9-]+-\d{2}$")
REPO_REL_RE = re.compile(r"^(?!/)(?!.*(?:^|/)\.\.(?:/|$)).+")
REQUIRED_LINKAGE = {"design", "inventory", "registry", "construction_plane"}


class AuditError(RuntimeError):
    """Fail-closed audit error."""


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def repo_root() -> Path:
    proc = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        capture_output=True,
        text=True,
        check=False,
    )
    if proc.returncode != 0:
        raise AuditError("Not inside a git repository")
    return Path(proc.stdout.strip()).resolve()


def load_json(path: Path) -> Dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise AuditError(f"input file not found: {path}") from exc
    except json.JSONDecodeError as exc:
        raise AuditError(f"invalid JSON: {path}: {exc}") from exc
    if not isinstance(payload, dict):
        raise AuditError("input payload must be object")
    return payload


def dump_json(path: Path, payload: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def dump_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not content.endswith("\n"):
        content += "\n"
    path.write_text(content, encoding="utf-8")


def ensure_repo_rel_path(value: Any, field: str) -> str:
    if not isinstance(value, str) or re.match(REPO_REL_RE, value) is None:
        raise AuditError(f"{field} must be repo-relative path without '..': {value!r}")
    return value


def parse_linkage_targets(value: Any) -> Set[str]:
    if isinstance(value, list):
        out: Set[str] = set()
        for item in value:
            if isinstance(item, str) and item.strip():
                out.add(item.strip())
        return out
    if isinstance(value, dict):
        out = set()
        for key, flag in value.items():
            if flag:
                out.add(str(key))
        return out
    return set()


def validate_input(payload: Dict[str, Any], root: Path) -> None:
    required = ["round_id", "scope_baseline_ref", "linkage_targets", "changed_assets", "superpower_ref"]
    for key in required:
        if key not in payload:
            raise AuditError(f"missing required field: {key}")

    round_id = payload["round_id"]
    if not isinstance(round_id, str) or ROUND_ID_RE.match(round_id) is None:
        raise AuditError(f"round_id invalid: {round_id!r}")

    scope_ref = ensure_repo_rel_path(payload["scope_baseline_ref"], "scope_baseline_ref")
    if not (root / scope_ref).exists():
        raise AuditError(f"scope_baseline_ref not reachable: {scope_ref}")

    changed_assets = payload["changed_assets"]
    if not isinstance(changed_assets, list) or not changed_assets:
        raise AuditError("changed_assets must be a non-empty list")

    for idx, path in enumerate(changed_assets):
        ensure_repo_rel_path(path, f"changed_assets[{idx}]")

    superpower_ref = payload["superpower_ref"]
    if not isinstance(superpower_ref, str) or not superpower_ref.strip():
        raise AuditError("superpower_ref must be non-empty string")


def run_audit(payload: Dict[str, Any], root: Path, report_rel: str) -> Dict[str, Any]:
    validate_input(payload, root)

    linkage = parse_linkage_targets(payload["linkage_targets"])
    missing_items: List[str] = []
    blocking_risks: List[str] = []
    recommended_actions: List[str] = []

    missing_scopes = sorted(REQUIRED_LINKAGE - linkage)
    if missing_scopes:
        missing_items.append("linkage_targets missing scopes: " + ", ".join(missing_scopes))
        blocking_risks.append("incomplete linkage scope")
        recommended_actions.append("add missing linkage_targets scopes before proceeding")

    for rel in payload["changed_assets"]:
        if not (root / rel).exists():
            missing_items.append(f"changed asset unreachable: {rel}")
            blocking_risks.append("changed_assets contains unreachable path")
            recommended_actions.append("synchronize changed_assets with actual repo files")

    scope_text = (root / payload["scope_baseline_ref"]).read_text(encoding="utf-8")
    conflict_marked = "semantic_conflict: true" in scope_text or bool(payload.get("semantic_conflict"))
    if conflict_marked and not payload.get("decision_snapshot_ref"):
        blocking_risks.append("superpower semantic conflict unresolved without decision snapshot")
        recommended_actions.append("attach architect decision_snapshot_ref before close")

    if not missing_items and not blocking_risks:
        recommended_actions.append("proceed to AP-034 linked artifacts update")

    decision = "pass" if not blocking_risks else "fail"
    reason = "linkage audit passed" if decision == "pass" else "linkage audit blocked"

    report_lines = [
        "# M6 Construction Linkage Audit Report",
        "",
        f"- timestamp: {now_iso()}",
        f"- round_id: {payload['round_id']}",
        f"- superpower_ref: {payload['superpower_ref']}",
        f"- decision: {decision}",
        f"- reason: {reason}",
        "",
        "## Missing Items",
    ]
    if missing_items:
        for item in missing_items:
            report_lines.append(f"- {item}")
    else:
        report_lines.append("- (none)")

    report_lines.extend(["", "## Blocking Risks"])
    if blocking_risks:
        for item in blocking_risks:
            report_lines.append(f"- {item}")
    else:
        report_lines.append("- (none)")

    report_lines.extend(["", "## Recommended Actions"])
    for item in recommended_actions:
        report_lines.append(f"- {item}")

    dump_text(root / report_rel, "\n".join(report_lines) + "\n")

    result = {
        "linkage_report_ref": report_rel,
        "missing_items": missing_items,
        "blocking_risks": blocking_risks,
        "recommended_actions": recommended_actions,
        "decision": decision,
        "reason": reason,
    }
    return result


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Run construction linkage audit")
    parser.add_argument("--input", required=True, help="Input JSON path")
    parser.add_argument("--output", required=True, help="Output JSON path")
    parser.add_argument("--report", required=True, help="Repo-relative report path")
    return parser


def main() -> int:
    args = build_parser().parse_args()
    root = repo_root()

    in_path = Path(args.input)
    if not in_path.is_absolute():
        in_path = root / in_path
    out_path = Path(args.output)
    if not out_path.is_absolute():
        out_path = root / out_path

    try:
        report_rel = ensure_repo_rel_path(args.report, "report")
        payload = load_json(in_path)
        result = run_audit(payload, root, report_rel)
        dump_json(out_path, result)
        out_abs = out_path
        try:
            display_path = out_abs.relative_to(root).as_posix()
        except ValueError:
            # Keep CLI output stable when caller provides an absolute output path outside repo.
            display_path = out_abs.as_posix()
        print(display_path)
        if result["decision"] != "pass":
            return 3
        return 0
    except AuditError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


