def _load_jsonl_events(path: Path) -> List[Dict[str, Any]]:
    if not path.exists():
        raise ContractError(f"{path}: missing round evidence log")

    events: List[Dict[str, Any]] = []
    for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except json.JSONDecodeError as exc:
            raise ContractError(f"{path}: invalid JSONL line {line_no}: {exc}") from exc
        if not isinstance(item, dict):
            raise ContractError(f"{path}: line {line_no} must be JSON object")
        events.append(item)
    return events


def _resolve_round_owner_root(round_dir: Path) -> Optional[Path]:
    parts = round_dir.resolve().parts
    marker = ("runtime_data", "execution", "evidence", "construction-plane")
    for idx in range(0, len(parts) - len(marker) + 1):
        if tuple(parts[idx : idx + len(marker)]) == marker:
            if idx == 0:
                return Path("/")
            return Path(*parts[:idx])
    return None


